"""AI release notes: draft "What's Changed" from PRs merged since the previous
release, then update the release body (any existing body is preserved).

Provider-agnostic: any OpenAI-compatible endpoint via AI_BASE_URL / AI_MODELS / AI_API_KEY.
Single bounded model call; the draft is clearly marked so a human can edit it.
"""
from __future__ import annotations

import json
import os
import re
import sys
import time
import urllib.error
import urllib.parse
import urllib.request

AI_BASE_URL = os.environ.get(
    'AI_BASE_URL', 'https://generativelanguage.googleapis.com/v1beta/openai').rstrip('/')
AI_MODELS = [m.strip() for m in os.environ.get(
    'AI_MODELS', 'gemini-3.5-flash,gemini-3.5-flash-lite').split(',') if m.strip()]
AI_API_KEY = os.environ.get('AI_API_KEY', '')
GH_TOKEN = os.environ.get('GH_TOKEN', '')
REPO = os.environ.get('GITHUB_REPOSITORY', '')
TAG = os.environ.get('TAG', '')
SUMMARY_PATH = os.environ.get('GITHUB_STEP_SUMMARY', '')
API = os.environ.get('GITHUB_API_URL', 'https://api.github.com').rstrip('/')
TRANSIENT = {429, 500, 502, 503, 504}


def gh(path: str, data: dict | None = None, method: str = 'GET'):
    body = json.dumps(data).encode() if data is not None else None
    req = urllib.request.Request(
        f'{API}{path}', data=body, method=method,
        headers={
            'Authorization': f'Bearer {GH_TOKEN}',
            'Accept': 'application/vnd.github+json',
            'X-GitHub-Api-Version': '2022-11-28',
        })
    with urllib.request.urlopen(req, timeout=30) as r:
        return json.loads(r.read().decode())


def chat(prompt: str, max_tokens: int = 1200) -> str:
    last_err: Exception | None = None
    for model in AI_MODELS:
        for attempt in range(3):
            try:
                req = urllib.request.Request(
                    f'{AI_BASE_URL}/chat/completions',
                    data=json.dumps({
                        'model': model,
                        'messages': [{'role': 'user', 'content': prompt}],
                        'max_tokens': max_tokens,
                        'temperature': 0.3,
                    }).encode(),
                    headers={
                        'Authorization': f'Bearer {AI_API_KEY}',
                        'Content-Type': 'application/json',
                    }, method='POST')
                with urllib.request.urlopen(req, timeout=90) as r:
                    return json.loads(r.read().decode())['choices'][0]['message']['content']
            except urllib.error.HTTPError as e:
                last_err = e
                if e.code not in TRANSIENT:
                    break
                time.sleep(3 * (attempt + 1))
            except Exception as e:
                last_err = e
                time.sleep(3 * (attempt + 1))
    raise RuntimeError(f'all models failed, last error: {last_err}')


def strip_fences(text: str) -> str:
    text = text.strip()
    text = re.sub(r'^```(?:markdown|md)?\s*\n', '', text)
    return re.sub(r'\n```$', '', text).strip()


def main() -> int:
    releases = gh(f'/repos/{REPO}/releases?per_page=100')
    releases.sort(key=lambda r: r['created_at'])
    current = next((r for r in releases if r['tag_name'] == TAG), None)
    if current is None:
        print(f'release with tag {TAG!r} not found among {len(releases)} releases',
              file=sys.stderr)
        return 1
    idx = releases.index(current)
    prev = releases[idx - 1] if idx > 0 else None

    merged_to = current['created_at'][:10]
    if prev:
        q = f'repo:{REPO} is:pr is:merged merged:{prev["created_at"][:10]}..{merged_to}'
    else:
        q = f'repo:{REPO} is:pr is:merged merged:<={merged_to}'
    search = gh(f'/search/issues?q={urllib.parse.quote(q)}&per_page=100&sort=created&order=desc')
    prs = [{'n': i['number'], 'title': i['title'], 'url': i['html_url'],
            'labels': [l['name'] for l in i.get('labels', [])]}
           for i in search.get('items', [])]
    if not prs:
        print('no merged PRs found in the window; nothing to do')
        return 0

    since = prev['tag_name'] if prev else 'the beginning of the project'
    listing = '\n'.join(
        f"- #{p['n']} {p['title']} [{', '.join(p['labels']) or 'no labels'}]" for p in prs)
    prompt = (
        'Draft GitHub release notes for a software project.\n\n'
        f'PRs merged since {since}:\n{listing}\n\n'
        'Rules: markdown only, no code fences, no preamble. Start with a one-paragraph '
        'overview. Then sections "### Features", "### Fixes", "### Docs", "### Other" '
        '(drop empty ones). One bullet per PR, format: "- Title (#N)". Keep titles as-is. '
        'Maximum 400 words.')

    raw = chat(prompt)
    notes = strip_fences(raw)
    coverage = (f'<sub>Draft generated by AI from {len(prs)} merged PRs — please edit. '
                'agent-guardrails/ai-review</sub>')
    draft = f'{notes}\n\n{coverage}'

    existing = (current.get('body') or '').strip()
    body = (f'{existing}\n\n---\n\n{draft}') if existing else draft
    gh(f'/repos/{REPO}/releases/{current["id"]}', {'body': body}, method='PATCH')

    if SUMMARY_PATH:
        with open(SUMMARY_PATH, 'a') as f:
            f.write(draft + '\n')
    print(f'release notes updated for {TAG} ({len(prs)} PRs)')
    return 0


if __name__ == '__main__':
    missing = [v for v in ('GH_TOKEN', 'GITHUB_REPOSITORY', 'TAG') if not os.environ.get(v)]
    if missing:
        print(f'missing env vars: {missing}', file=sys.stderr)
        sys.exit(1)
    if not AI_API_KEY:
        print('AI_API_KEY is not set (org secret missing); skipping', file=sys.stderr)
        sys.exit(1)
    sys.exit(main())
